insert into public.services
  (id, name, channels, cancel, after_cancel, refund, warnings, notes, contact, sources, verification, last_verified)
values
($q$netflix$q$, $q$넷플릭스$q$, $q$["직접 결제","Apple","Google Play","통신사·제휴"]$q$::jsonb, $q${"direct":"멤버십 관리 페이지 > 해지 > 해지 완료","note":"로그아웃이나 앱 삭제로는 해지되지 않음. 이 방법이 유일한 해지 방법","other_channels":"스토어·통신사·결제 파트너로 가입했다면 해지 옵션이 안 보일 수 있음. 해당 파트너에서 해지"}$q$::jsonb, $q$확인 이메일이 계정 이메일로 발송됨(공식). 결제 주기 종료 전 해지 시 남은 기간 시청 가능$q$, $q$공식 페이지에는 환불 상세 항목 없음. 일반적으로 중도 환불 없음(블로그). 원치 않은 결제는 고객센터 문의$q$, $q$[]$q$::jsonb, null, null, $q$["https://help.netflix.com/ko/node/407"]$q$::jsonb, $q$page_read$q$, '2026-11-03'),
($q$youtube_premium$q$, $q$유튜브 프리미엄$q$, $q$["직접 결제(Google)","Apple","Google Play"]$q$::jsonb, $q${"direct":"youtube.com/paid_memberships > 멤버십 관리 > 비활성화 > 계속 > 취소 사유 선택 > 다음 > 취소 (컴퓨터 기준, 공식)","apple":"YouTube iOS 앱에서 가입했으면 Apple 계정 구독에서 취소","google_play":"Google Play 구독으로 이용 중이면 Google Play 계정 설정에서 취소"}$q$::jsonb, $q$결제 기간의 마지막 날까지 혜택 유지. 취소 후 재구독 전에는 청구 없음. 일시중지도 가능$q$, $q$공식 취소 페이지에는 환불 규정 없음. Apple 결제는 Apple 환불. 14일설은 미확인$q$, $q$[]$q$::jsonb, $q$이전 초안의 '프로필 > 구매 및 멤버십 > 프리미엄 > 멤버십 관리 > 해지'는 블로그 경로였고 공식 경로와 다름$q$, null, $q$["https://support.google.com/youtube/answer/6308278?hl=ko"]$q$::jsonb, $q$page_read$q$, '2026-11-03'),
($q$coupang_wow$q$, $q$쿠팡 와우 멤버십$q$, $q$["직접 결제"]$q$::jsonb, $q${"direct":"마이쿠팡 > 와우 멤버십 > 해지하기 (앱·PC)","restrictions":"은행 서비스 점검 시간에는 해지 불가. 쿠팡플레이 패스 회원은 패스를 먼저 해지"}$q$::jsonb, $q$이용했다면 종료 예정일까지 혜택 유지. 와우 해지 시 쿠팡플레이 와우 혜택도 해지(일반 회원이면 쿠팡플레이 이용 가능)$q$, $q$당월 혜택을 이용하지 않았다면 당월 월회비 환불(최대 7일, 일부 해외카드 14일). 이용했다면 환불 없음$q$, $q$["무료체험 중에는 즉시 해지할 수 없음. 해지를 신청하면 체험 종료 예정일까지 혜택이 유지된 뒤 자동으로 해지됨"]$q$::jsonb, $q$2025년 12월 해지 절차가 2단계로 간소화됐다는 보도(기사). 사용자 화면에는 표시되지 않는 내부 메모$q$, null, $q$["https://news.coupang.com/archives/64216/","https://www.mt.co.kr/living/2025/12/12/2025121211154258298"]$q$::jsonb, $q$official_search$q$, '2026-11-03'),
($q$naver_plus$q$, $q$네이버플러스 멤버십$q$, $q$["직접 결제(네이버페이)"]$q$::jsonb, $q${"direct":"[정기결제 해지: 다음 회차부터 결제 중단] 네이버플러스 마이 멤버십 > 오른쪽 위 설정(톱니바퀴) > 네이버플러스 멤버십 관리 > 네이버플러스 멤버십 해지하기 > 이번 이용 기간 확인 후 '정기결제 해지' > 해지하기. N+스토어 앱(마이쇼핑 > 설정 > 멤버십 해지하기)이나 네이버 앱(마이 > 설정 > 멤버십 해지하기)에서도 같은 방식으로 가능","immediate":"[멤버십 즉시 종료: 현재 회차 결제 취소·환불] 같은 경로(마이 멤버십 > 설정 > 네이버플러스 멤버십 관리 > 네이버플러스 멤버십 해지하기)에서 이번 이용 기간 확인 후 '멤버십 즉시 종료하기' > 환불 예상 금액과 회수/적립예정 취소 포인트 확인 > 해지하기. N+스토어 앱·네이버 앱 설정에서도 가능. 디지털 콘텐츠를 전혀 사용하지 않았을 때만 '즉시 종료' 버튼이 나타나고, 그 외에는 정기결제 해지만 가능","annual":"연간 이용권(12회차를 1개월 단위로 지급)은 정기결제 해지 과정에서 둘 중 하나를 고름. ① 연간 이용권 사용 후 정기결제 해지: 12회차까지 모두 쓴 뒤 자동결제되지 않음 ② 연간 이용권 중도 해지: 이번 회차까지 이용 후 종료되고, 미사용분은 환불 수수료를 차감하고 환불. 이미 예약한 연간 이용권을 취소하고 월간으로 돌아가려면 정기결제를 해지한 뒤 '정기결제 다시 등록하기'","deadline":"청약철회 기한은 이용 시작 다음 날부터 7일 이내. 기한 이전에 즉시 종료하면 100% 환불, 기한 이후에 즉시 종료하면 90% 환불","restrictions":"이용 기간이 종료된 회차는 사용 여부와 상관없이 즉시 종료(환불) 불가. Xbox PC Game Pass와 스포티파이 프리미엄 베이직은 이용권이 지급되면 바로 사용 처리되어 즉시 종료 불가. 연간 이용권 회차(1개월 단위)의 마지막 날에는 중도 해지 불가. 이미 정기결제가 해지된 상태에서는 '멤버십 해지하기' 버튼이 나타나지 않음. 관리 페이지는 멤버십 가입 아이디로 로그인해야 접속 가능"}$q$::jsonb, $q$정기결제 해지: 이번 회차 이용 기간까지 혜택이 유지되고 이후 결제되지 않으며, 디지털 콘텐츠 업그레이드도 자동 해지됨. 다시 이용하려면 멤버십 관리에서 '정기결제 등록하기'를 누르면 해지가 취소되고 멤버십이 연장됨.
멤버십 즉시 종료: 즉시 비가입자로 전환되고 디지털 콘텐츠 혜택이 모두 회수되며, 적립됐거나 적립 예정인 금액은 회수·소멸됨. 이용권 보관함의 무료 이용권은 모두 소멸되어 복구되지 않고, 취소·환불한 당일은 재가입이 제한되며 다음 날부터 가능함$q$, $q$[즉시 종료, 월간] 디지털 콘텐츠를 전혀 사용하지 않았을 때만 가능. 청약철회 기한 이전 100%, 이후 90% 환불.
[즉시 종료, 연간 1회차] 기한 이전 100%, 기한 이후 490원(회차 1개 비용의 10%) 공제 후 환불.
[즉시 종료, 연간 2회차 이후] 연간 이용권 금액에서 '①1회차~직전 회차: 사용한 개월 수 × 4,900원(정가)'과 '②현재 회차: 이용 시작 7일 이내 0원, 7일 이후 490원'을 더한 수수료를 공제하고 환불.
[연간 중도 해지] 사용한 개월 수 × 4,900원을 수수료로 차감하고 환불. 수수료가 연간 이용권 금액보다 크면 회사 지정 계좌로 초과분을 입금해야 하고, 환불 예상 금액이 마이너스로 표시되면 네이버플러스 멤버십 전용 고객센터에 문의.
[환불 시점] 신용·체크카드는 취소 완료일로부터 3~5영업일 이내 카드 결제 취소, 계좌 간편결제는 즉시 환불, 무통장입금은 본인계좌 환불 시 1영업일 후(정산액 적립은 즉시), 휴대폰 소액결제는 결제 당월이면 승인 취소·익월이면 환불 정산액으로 적립, Npay 머니는 즉시 재충전, Npay 포인트는 즉시 재적립. 결과는 Npay 결제내역 > 콘텐츠에서 확인$q$, $q$["즉시 종료를 하면 현재 이용 중인 회차가 취소·환불되고, 이미 적립됐거나 적립 예정인 금액은 회수·소멸됨. 차감할 Npay 적립 포인트가 부족하면 마이너스 금액으로 처리됨","즉시 종료 이후에는 철회할 수 없고, 취소·환불되면 즉시 비가입자로 전환됨","멤버십은 현재 회차의 마지막 날 다음 회차가 정기결제됨. 그날 결제된 금액을 돌려받으려면 즉시 종료가 아니라 정기결제 해지로 진행해야 함. 정기결제 당일(회차 마지막 날)에 해지하면 이용 기간이 시작되지 않은 회차가 자동 환불됨","이용권 보관함에 이용권이 있으면 정기결제를 해지해도 멤버십 기간이 자동 연장됨. 무료 이용권으로 연장되면 디지털 콘텐츠 업그레이드 요금이 청구되므로, 결제를 원치 않으면 업그레이드를 별도로 해지해야 함","무료 이용권을 쓰는 중에 '해지하기' 버튼이 보이지 않는다면 다음 회차 이용권(월간·연간)은 결제되지 않음","넷플릭스 이용권을 쓰다가 이번 이용 기간 종료로 멤버십이 끝나거나, 다음 기간부터 다른 콘텐츠·패밀리 멤버로 바꾸거나, 더 저렴한 넷플릭스 이용권으로 바꾸면 이번 회차 마지막 날 23시 30분부터 24시까지 넷플릭스 시청이 제한될 수 있음(시스템 사정에 따라 시간은 달라질 수 있음)"]$q$::jsonb, $q$공식 도움말(help.naver.com, 네이버플러스 멤버십 해지·환불 안내) 본문을 사용자가 복사해 제공한 내용을 기준으로 2026-11-04에 갱신함. 에이전트가 네이버 도메인에 직접 접속하지는 못함. 이전의 블로그 기반 내용(웰컴 쿠폰 차감 사례 등)은 공식 본문에 없어 제거함. 정책은 바뀔 수 있으니 해지 전 공식 안내를 한 번 더 확인할 것$q$, null, $q$["https://help.naver.com/service/23168/bookmark/20281?osType=COMMONOS"]$q$::jsonb, $q$page_read$q$, '2026-11-04'),
($q$disney_plus$q$, $q$디즈니+$q$, $q$["직접 결제","Apple","Google Play","통신사"]$q$::jsonb, $q${"direct":"disneyplus.com/account/cancel-subscription 접속 > 멤버십 취소 (또는 프로필 > 계정 > 멤버십)","third_party":"앱스토어·제3자 구독은 해당 제3자의 취소·환불 정책 적용"}$q$::jsonb, $q$취소는 결제 주기 종료 시점에 발효. 그때까지 이용 가능. 무료체험·프로모션 코드 구독은 즉시 발효될 수 있음$q$, $q$취소 후 남은 기간은 환불 없음. 다만 즉시 취소+비례 환불은 고객센터(온라인 채팅·전화)로 요청 가능. 시청 이력이 없으면 위약금 없음, 있으면 정상 구독료의 최대 10% 위약금 차감. 결제 후 7일 이내이고 시청 이력이 없으면 청약철회 가능$q$, $q$["읽은 페이지는 '[이전]' 정책(2025-05-16 시행)이고, 개정 정책은 신규 2026-05-08, 기존 회원 2026-06-12부터 적용됨. 오늘 기준 개정 정책이 적용되므로 환불 규정은 개정 정책 본문으로 다시 확인해야 함"]$q$::jsonb, null, null, $q$["https://www.disneyplus.com/ko-kr/welcome/cancellation-and-refund-policy","https://www.disney.co.kr/notice/update-20260512"]$q$::jsonb, $q$page_read$q$, '2026-11-03'),
($q$tving$q$, $q$티빙$q$, $q$["직접 결제","Apple","Google Play","제휴(디즈니+ 연동 등)","더블 이용권"]$q$::jsonb, $q${"direct":"고객센터 '해지/환불 신청' 메뉴(문의 유형 '이용권 해지/환불'). 블로그는 MY > 이용권 내역 > 변경/해지 경로도 안내(미대조)","deadline":"결제 예정일 최소 24시간 전에 신청 (안내문마다 표현 차이)","partners":"디즈니+ 연동 이용권은 구매처(티빙 또는 디즈니+)에서 해지. 더블 이용권(웨이브 연동)은 티빙에서만 변경·해지","store":"인앱결제는 스토어 구독 관리(검색 결과에 직접 명시되진 않음)"}$q$::jsonb, $q$신청 즉시 자동해지되지 않고 순차 처리됨$q$, $q$구매 후 7일 이내이고 시청·다운로드 이력이 없으면 철회 가능. 그 외에는 사용 일수와 수수료 제외 후 환불$q$, $q$[]$q$::jsonb, null, $q$1670-1525 (평일 09~17시, 점심 13~14시 제외), tving@cj.net$q$, $q$["https://www.tving.com/qna/f390.do","https://www.tving.com/membership/double"]$q$::jsonb, $q$official_search$q$, '2026-11-03'),
($q$wavve$q$, $q$웨이브$q$, $q$["직접 결제","SKT 구독 연동","FLO 결합","티빙 더블 이용권"]$q$::jsonb, $q${"direct":"결제 당일을 제외한 이용기간 중 언제든 자동결제 해지 가능. 고객센터를 통한 자동결제해지 신청은 본인만 가능","partners":"SKT 구독서비스 연동은 SKT에서만 구매·해지, FLO 결합상품은 FLO에서만","double":"티빙·웨이브 더블 이용권은 티빙에서 변경·해지(티빙 안내 기준)"}$q$::jsonb, $q$추가 결제 없음. 다음 결제 예정일까지 이용 가능$q$, $q$구매 후 7일 이내 미사용이면 청약철회(고객센터 > 1:1문의, 접수 후 3영업일 내 결제 취소·환불). 이후엔 결제 주기 시작일부터 해지일까지 일할 계산 차감. 12개월 이용권은 1개월 이용권의 할인 미적용 정상가 기준으로 계산$q$, $q$[]$q$::jsonb, null, null, $q$["https://www.wavve.com/customer/faq","https://www.wavve.com/agreement/paid"]$q$::jsonb, $q$official_search$q$, '2026-11-03'),
($q$chatgpt$q$, $q$ChatGPT (Plus/Pro/Business)$q$, $q$["웹(chatgpt.com)","Apple","Google Play","Business 워크스페이스"]$q$::jsonb, $q${"web":"로그인 > 계정 메뉴 > Settings > Billing > Cancel plan 아래 Cancel","ios":"설정 > 이름 > 구독 > ChatGPT > 구독 취소 > 확인","android":"Play 스토어 앱 > 구독 > ChatGPT > 구독 취소, 또는 Google Play 웹 > Manage > Cancel subscription","business":"계정 메뉴 > Workspace settings > Billing > Manage plan > Cancel subscription","cannot_sign_in":"직접 결제인데 계정 이메일을 쓸 수 없으면 OpenAI Support에 문의. 계정 이메일 또는 결제 이메일과 카드 끝 4자리·만료일·청구 주소·최근 결제일 중 2가지 필요(카드번호 전체는 보내지 말 것)"}$q$::jsonb, $q$취소는 이후 갱신만 중단. 이전 결제는 자동 환불되지 않음$q$, $q$공식 취소 페이지는 환불을 자동 처리하지 않는다는 점만 명시. 별도 환불 정책 페이지 확인 필요$q$, $q$["앱 삭제로는 취소되지 않음","웹에서 계정을 삭제해도 Apple 구독은 취소되지 않음. Apple에서 먼저 취소","결제만 멈추려면 계정 삭제 불필요","Billing이 안 보이면 다른 브라우저에서 같은 계정으로 로그인"]$q$::jsonb, null, null, $q$["https://help.openai.com/en/articles/7232927-how-do-i-cancel-my-subscription-for-chatgpt-plus-or-chatgpt-pro"]$q$::jsonb, $q$page_read$q$, '2026-11-03'),
($q$claude$q$, $q$Claude (Pro/Max/Ultra)$q$, $q$["웹·데스크톱","iOS 앱","Android 앱"]$q$::jsonb, $q${"web":"claude.ai 또는 데스크톱 앱 왼쪽 아래 이름 > Settings > Billing > Cancel","ios":"iOS 앱 오른쪽 위 이름 > Billing > Manage subscription > 안내에 따라 취소. 앱을 지웠다면 Apple 구독 해지 안내 이용","android":"Android 앱 오른쪽 위 이름 > Billing > Manage subscription. 앱을 지웠다면 Google Play 구독에서 취소"}$q$::jsonb, $q$취소는 현재 결제 기간 종료 시 발효, 그때까지 유료 플랜 사용 가능$q$, $q$공식 페이지에는 일반 환불 규정 없음. Max·Ultra·Team에 포함된 월간 API 크레딧은 구매한 것이 아니라 환불 불가, 주기 말 소멸. 취소·환불 시 새 월간 크레딧은 중단되고 이미 있는 크레딧은 만료까지 사용 가능$q$, $q$["다음 결제일 최소 24시간 전에 취소해야 다음 기간 요금이 청구되지 않음"]$q$::jsonb, $q$이전 초안은 Pro/Max만 언급. 현재 공식 문서는 Pro·Max·Ultra. 모바일 경로가 이름(initials) 기준 Billing 메뉴임$q$, null, $q$["https://support.claude.com/en/articles/8325617-cancel-your-pro-max-or-ultra-subscription"]$q$::jsonb, $q$page_read$q$, '2026-11-03'),
($q$gemini$q$, $q$제미나이 (Google AI Pro/Ultra)$q$, $q$["Google One(웹·Android)","Apple(iOS)","Google Play","Google 스토어","Workspace 관리자"]$q$::jsonb, $q${"web":"gemini.google.com 하단 설정 및 도움말 > 구독 관리 > Google One 설정이 열림 > 멤버십 취소 > 취소 (공식). 또는 Google One에서 멤버십 관리","android":"Gemini 앱 프로필 사진·이니셜 > 구독 관리 > 멤버십 취소 (검색 결과 기준, 해당 페이지 Android 탭은 미열람)","ios":"Google 앱으로 구독했다면 Apple 설정의 구독에서 Google One 선택 후 취소 (검색 결과 기준, iOS 탭 미열람)","google_play_store":"Google 계정 구독 관리 페이지에서 해당 구독 선택 > 구독 취소","workspace":"Gemini 부가기능은 최고 관리자 계정으로 관리 콘솔 > 결제 > 구독에서 취소. 최고 관리자가 아니면 취소 불가"}$q$::jsonb, $q$이미 결제한 기간은 계속 이용(Google Play 기준 안내). 취소하면 Pro 전용 Gemini 기능과 Google One 추가 스토리지 혜택이 사라짐$q$, $q$공식(Google One 정책, 한국 거주자): 사용을 개시하지 않았다면 구매일로부터 7일 이내 철회·전액 환불 가능, Google One 지원팀에 문의. 그 외 대부분의 국가·지역에서 구입한 스토리지 요금제는 환불되지 않음. Play 스토어 구매는 Google Play 환불 정책, Apple 구매는 Apple 지원팀$q$, $q$["Google AI 요금제는 Google One 멤버십의 일부라 Gemini 앱에서 '구독 관리'를 눌러도 Google One 설정으로 이동함","취소하면 추가 스토리지가 모두 사라지고 결제 주기 종료 후 무료 한도를 넘을 수 있음. 한도를 초과하면 Gmail 송수신, Drive 업로드, 포토 백업이 제한되고, 2년 이상 초과 시 Google 계정의 콘텐츠가 삭제될 수 있음(공식). 취소 전 스토리지 정리 필요","사용하지 않은 AI 크레딧은 요금제 해지 시 소멸(검색 결과 기준, 미대조)"]$q$::jsonb, null, null, $q$["https://support.google.com/gemini/answer/14517446?hl=ko&co=GENIE.Platform%3DDesktop","https://support.google.com/googleone/answer/2736362?hl=ko","https://support.google.com/googleone/answer/9056360?hl=ko&co=GENIE.Platform%3DDesktop"]$q$::jsonb, $q$page_read$q$, '2026-11-03'),
($q$notion$q$, $q$노션 (유료 플랜)$q$, $q$["웹(직접 결제: 카드·Apple Pay·Google Pay)","Apple App Store","Google Play"]$q$::jsonb, $q${"direct":"데스크톱이나 웹에서 왼쪽 사이드바 설정(Settings) > 결제(Billing) > 플랜 변경(Change plan) > 바꿀 플랜(Free) 선택 후 계속(Continue) > 의견을 남기고 다운그레이드(Downgrade). 완료하면 확인 메시지와 현재 플랜이 끝나는 날짜가 표시됨. 취소하기 전까지는 자동으로 갱신됨","store":"모바일에서 구매한 구독은 Apple App Store나 Google Play 스토어에서 관리. App Store로 구독했다면 취소·환불 등 구독 문제는 Apple에 직접 문의해야 함. Google Play에서 취소하는 구체적인 단계는 노션 공식 페이지에 나와 있지 않음","restrictions":"플랜 변경·취소는 데스크톱이나 웹에서만 가능하고 모바일 앱에서는 할 수 없음. 모바일에서 구매한 Plus 구독은 멤버가 1명뿐인 워크스페이스에만 가능"}$q$::jsonb, $q$취소한 뒤에도 현재 청구 주기가 끝날 때까지 모든 유료 기능을 쓸 수 있고, 계정은 청구 주기가 끝날 때 다운그레이드됨.
다운그레이드하면 기능에 영향이 있을 수 있어 노션은 변경 전에 별도 안내 문서(notion.com/help/plan-downgrade)를 읽도록 권함. 그 문서는 아직 확인하지 못함. 무료 한도를 넘으면 일부 페이지가 읽기 전용이 될 수 있다는 내용은 블로그 기준이라, 사전에 내보내기를 해 두는 것을 권장$q$, $q$[플랜 변경 도움말] 가입을 실수로 했다면 앱 안의 지원이나 이메일로 문의. 월 결제는 가입 후 3일 이내, 연 결제는 가입 후 30일 이내에 다운그레이드하면 전액(비례 계산 아님) 환불.
[환불 정책] 실수로 유료 구독했다면 앱 내 지원으로 워크스페이스 소유자 이메일 또는 결제 이메일로 환불 요청. 대부분 월 결제는 인보이스 발행 후 3일 이내, 연 결제는 30일 이내면 처리 가능. 실수로 추가된 멤버는 인보이스 발행일로부터 3일 이내 요청 시 비례 환불(멤버를 먼저 제거). 미사용 크레딧은 환불 가능, 일부라도 사용하면 불가.
[결제 경로] Apple 결제는 Apple에 직접 요청, 웹·Google Pay 결제는 노션에 요청$q$, $q$["노션의 플랜은 워크스페이스 단위로 적용되고 청구됨. 워크스페이스가 여러 개라면 각각 변경해야 함","멤버를 제거해도 그 자리의 금액은 크레딧으로 돌려받지 못하고, 해당 청구 기간이 끝날 때까지 다른 사용자가 그 자리를 쓸 수 있음","결제가 실패하면 이메일로 알려 주고 한 달 안에 최대 8번까지 다시 결제를 시도하며, 이후 제한된 접근 상태를 거쳐 Free 플랜으로 내려감"]$q$::jsonb, $q$공식 도움말 'Change your plan'(notion.com/help/upgrade-or-downgrade-your-plan)과 환불 정책(notion.com/help/refunds) 본문을 2026-11-04에 읽고 갱신함. 다운그레이드 이후 기능 변화(notion.com/help/plan-downgrade)와 Google Play 구독의 구체적인 취소 단계는 확인하지 못함. 실제 계정 화면에서 눌러 확인한 것은 아님$q$, null, $q$["https://www.notion.com/help/upgrade-or-downgrade-your-plan","https://www.notion.com/help/refunds"]$q$::jsonb, $q$page_read$q$, '2026-11-04')
on conflict (id) do update set
  name = excluded.name,
  channels = excluded.channels,
  cancel = excluded.cancel,
  after_cancel = excluded.after_cancel,
  refund = excluded.refund,
  warnings = excluded.warnings,
  notes = excluded.notes,
  contact = excluded.contact,
  sources = excluded.sources,
  verification = excluded.verification,
  last_verified = excluded.last_verified;
